mapper.sql:
WHERE 1=1

  AND (UPPER(T1.GROUP_ID) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(T1.GROUP_NAME) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.SYSTEM_ID,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.GROUP_ID = #{groupId}
AND T1.GROUP_NAME LIKE '%'||#{groupName}||'%'
AND T1.SYSTEM_ID = #{systemId}
AND T1.TECH_ROLE_CD = #{techRoleCd}
AND T1.ENV_CD = #{envCd}
AND T1.TIER_CD = #{tierCd}
AND T1.STATUS_CD = #{statusCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.GROUP_ID, T1.GROUP_NAME, T1.SYSTEM_ID, T1.TECH_ROLE_CD, T1.ENV_CD, T1.TIER_CD, T1.STATUS_CD,
           T1.ACTIVE_NODES, T1.STANDBY_NODES, T1.DR_NODES, T1.REMARK,
           T1.REG_USER_ID, T1.REG_DTM, T1.CHG_USER_ID, T1.CHG_DTM
      FROM TB_IF_SERVER_GROUP_PILOT T1

     ORDER BY T1.REG_DTM DESC, T1.GROUP_ID ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.update:
UPDATE TB_IF_SERVER_GROUP_PILOT SET GROUP_NAME=#{groupName}, SYSTEM_ID=#{systemId}, TECH_ROLE_CD=#{techRoleCd},
  ENV_CD=#{envCd}, TIER_CD=#{tierCd}, STATUS_CD=#{statusCd},
  ACTIVE_NODES=#{activeNodes}, STANDBY_NODES=#{standbyNodes}, DR_NODES=#{drNodes},
  REMARK=#{remark}, CHG_USER_ID=#{chgUserId}, CHG_DTM=#{chgDtm}
 WHERE GROUP_ID=#{groupId}
